  fd2_s: (a, b, n, m, r) => `Dividir una fracción entre ${n} es repartirla en ${n} partes: se multiplica el denominador. ${a}/${b} : ${n} = ${a}/(${b} × ${n}) = ${a}/${m}${r === `${a}/${m}` ? "" : ` = <b>${r}</b>`}.`.replace(`= ${a}/${m}.`, `= <b>${a}/${m}</b>.`),
