  cr_hueco_s: (d, ans) => `${d === 2 ? "Entre 2, el número tiene que acabar en cifra par" : d === 5 ? "Entre 5, tiene que acabar en 0 o en 5" : "Entre 10, tiene que acabar en 0"}: en el hueco vale <b>${ans.join(", ")}</b>.`,
  esc_q: (e, cm, raw) => `En un ${raw < 25000 ? "plano" : "mapa"} a escala 1 : ${e}, dos puntos están a ${cm} cm. ¿A cuántos metros están en la realidad?`,
