  cm_f: ["Denominador común", f => `Numerador de ${f}`],
  cm_s: (d1, l1, d2, l2, m, ea, eb) => `Múltiplos de ${d1}: ${l1}… Múltiplos de ${d2}: ${l2}… El primero que coincide es el <b>${m}</b>. ${ea}; ${eb}.`,
  cm_ord_q: l => `Ordena de menor a mayor: <b>${l}</b>.`,
  cm_ord_s: (m, eqs, nums, res) => `Paso las tres al denominador común ${m}: ${eqs}. Ordeno los numeradores: ${nums}. De menor a mayor: <b>${res}</b>.`,
  ml_val_q: (v, d) => `En el número <b>${v}</b>, ¿qué valor tiene la cifra ${d}?`,
  ml_val_o: d => [`${d} ${d === 1 ? "décima" : "décimas"}`, `${d} ${d === 1 ? "centésima" : "centésimas"}`, `${d} ${d === 1 ? "milésima" : "milésimas"}`, `${d} ${d === 1 ? "unidad" : "unidades"}`],
  ml_val_s: (dd, d, i, v) => `Tras la coma: ${dd[0]} ${dd[0] === 1 ? "décima" : "décimas"}, ${dd[1]} ${dd[1] === 1 ? "centésima" : "centésimas"} y ${dd[2]} ${dd[2] === 1 ? "milésima" : "milésimas"}. El ${d} está en las ${["décimas", "centésimas", "milésimas"][i]}: vale <b>${d} ${["décima", "centésima", "milésima"][i]}${d === 1 ? "" : "s"}</b> (${v}).`,
  ml_esc_q: (u, m) => `Escribe con cifras: <b>${u ? `${u} ${u === 1 ? "unidad" : "unidades"} y ` : ""}${m} ${m === 1 ? "milésima" : "milésimas"}</b>.`,
  ml_esc_s: (m, p, u, v) => `Las milésimas ocupan <b>tres</b> lugares tras la coma: ${m} ${m < 100 ? `tiene menos de tres cifras, así que relleno con ceros delante → ${p}` : `→ ${p}`}. Delante de la coma, ${u}. Número: <b>${v}</b>.`,
