  ml_cmp_s: (a, b, res, trampa) => `Igualo las cifras decimales con ceros: ${a} y ${b}. Comparo de izquierda a derecha: <b>${res}</b>.${trampa ? " (¡Tener más cifras no lo hace mayor!)" : ""}`,
  dd_u: ["yogures", "zumos", "cuadernos", "bolígrafos", "batidos", "rotuladores"],
