  dps0_q: (n, u, p, obj, q, B) => `Compras ${n} ${u} a ${p} € cada uno y ${obj} de ${q} €. Pagas con un billete de ${B} €. ¿Cuánto te devuelven, en euros?`,
  dps0_s: (n, u, p, a, q, t, B, r) => `Plan: primero multiplico, después sumo y al final resto. ${u[0].toUpperCase() + u.slice(1)}: ${n} × ${p} = ${a} €. Total: ${a} + ${q} = ${t} €. Cambio: ${B} − ${t} = <b>${r} €</b>. Compruebo sumando: ${t} + ${r} = ${B} ✔`,
  dps_nombres: [["Ana", "Luis"], ["Marta", "Pablo"], ["Leo", "Sara"], ["Nora", "Hugo"]],
  dps1_q: (a, x, b, y) => `${a} tiene ${x} € y ${b} tiene ${y} € más que ${a}. ¿Cuántos euros tienen entre los dos?`,
  dps1_s: (a, x, b, y, l, s) => `Plan: primero calculo lo de ${b} y después sumo. ${b}: ${x} + ${y} = ${l} €. Entre los dos: ${x} + ${l} = <b>${s} €</b>.`,
  dps_frutas: ["manzanas", "naranjas", "patatas", "cerezas", "tomates"],
  dps2_q: (k, fr, p, B) => `Compras ${k} kg de ${fr} a ${p} € el kilo y pagas con un billete de ${B} €. ¿Cuánto te devuelven, en euros?`,
  dps2_s: (k, p, k10, p100, prod, c, B, r) => `Primero, lo que cuestan: ${k} × ${p}. Sin comas, ${k10} × ${p100} = ${prod}; ${k} tiene 1 decimal y ${p}, 2: separo 3 cifras → ${c} €. Después, el cambio: ${B} − ${c} = <b>${r} €</b>.`,
  dps_regalos: ["un regalo", "una pizza grande", "un balón", "una tarta"],
  dps3_q: (n, obj, T, q) => `${n} amigos compran ${obj} de ${T} € y pagan entre todos a partes iguales. Además, cada uno se compra un refresco de ${q} €. ¿Cuánto gasta cada uno, en euros?`,
  dps3_s: (obj, T, n, x, q, r) => `Plan: primero divido y después sumo. Parte de ${obj}: ${T} : ${n} = ${x} €. Más el refresco: ${x} + ${q} = <b>${r} €</b>.`,
  s5_s: (a, b, k, down, f, v, r) => `De ${a} a ${b} se ${down ? (k === 1 ? "baja" : "bajan") : (k === 1 ? "sube" : "suben")} ${k === 1 ? "un peldaño" : `${k} peldaños`} de la escalera, y en superficie cada peldaño es × 100: se ${down ? "multiplica por" : "divide entre"} ${f}. ${v} ${down ? "×" : ":"} ${f} = <b>${r} ${b}</b>.`,
  du_ctx: [
    (a, b) => `Un tren sale a las ${a} y llega a las ${b}. ¿Cuánto dura el viaje?`,
    (a, b) => `Una película empieza a las ${a} y acaba a las ${b}. ¿Cuánto dura?`,
    (a, b) => `Una excursión sale a las ${a} y vuelve a las ${b}. ¿Cuánto tiempo dura?`,
    (a, b) => `Un partido empieza a las ${a} y termina a las ${b}. ¿Cuánto dura?`,
  ],
  du_f: ["Horas", "Minutos"],
  du_s: (a, h1, x, h2, hh, b, m2, sum, H, M) => `Cuento por saltos. De ${a} a ${h1}: ${x} min.${hh ? ` De ${h1} a ${h2}: ${hh} h.` : ""} De ${h2} a ${b}: ${m2} min. Total: ${hh ? `${hh} h y ` : ""}${x} + ${m2} = ${sum} min${sum >= 60 ? ` (y ${sum} min = 1 h ${sum - 60} min)` : ""} → <b>${H} h ${M} min</b>.`,
  du_min_q: (h, m) => `¿Cuántos minutos son <b>${h} h ${m} min</b>?`,
  du_min_s: (h, m, x, r) => `Cada hora son 60 minutos: ${h} × 60 = ${x}. Más ${m}: ${x} + ${m} = <b>${r} min</b>.`,
