  din_obj: ["un libro", "un balón", "unos patines", "un juego de mesa", "una mochila"],
  din_ah_q: (obj, P, T, A) => `Quieres comprar ${obj} de ${P} €. Ya tienes ${T} € y ahorras ${A} € cada semana. ¿Cuántas semanas tardarás en reunir el dinero?`,
  din_ah_s: (P, T, F, A, w) => `Te faltan ${P} − ${T} = ${F} €. Cada semana juntas ${A} €: ${F} : ${A} = <b>${w} semanas</b> (${w} × ${A} = ${F} €).`,
  din_ah_s2: (P, T, F, A, A2, k, w) => `Te faltan ${P} − ${T} = ${F} €. En 2 semanas juntas ${A} + ${A} = ${A2} €. ${F} : ${A2} = ${k}: necesitas ${k} veces 2 semanas, <b>${w} semanas</b>.`,
  din_u_q: (n, pl, P) => `Un paquete de ${n} ${pl} cuesta ${P} €. ¿Cuánto cuesta cada uno, en euros?`,
  tipo: ["agudo", "recto", "obtuso", "llano"],
  rl_q: h => `¿Qué ángulo forman las agujas del reloj a las <b>${h} en punto</b>? (Cuenta por el camino más corto.)`,
  rl_s: (h, s, g, otro, t) => `La aguja larga está en el 12 y la corta en el ${h}. Por el camino más corto hay ${s} ${s === 1 ? "espacio" : "espacios"} de 30°${otro ? ` (por el otro lado habría ${h}, más de media vuelta)` : ""}: ${s} × 30° = <b>${g}°</b>, un ángulo ${t}.`,
  rl_min_q: m => `¿Cuántos grados gira la aguja de los minutos en <b>${m} minutos</b>?`,
  rl_min_s: (m, g) => `En 60 minutos da una vuelta entera, 360°: cada minuto son 360° : 60 = 6°. En ${m} minutos: ${m} × 6° = <b>${g}°</b>.`,
  am_q: "¿Cuánto mide el ángulo rojo? (Un lado está sobre el 0 de la fila de fuera.)",
  am_s: (a, b, t, ag) => `Un lado está sobre el 0 de la fila de fuera, así que leo en esa fila donde pasa el otro lado: <b>${a}°</b>. En la fila de dentro pone ${b}: no es la buena. Además, el ángulo es ${t}: ${ag ? "tiene que medir menos de 90°" : "tiene que medir más de 90°"}.`,
  rg_nom: n => n === 3 ? "triángulo equilátero" : n === 4 ? "cuadrado" : `${S.po_n[n]} regular`,
  rg_ang_q: nm => `¿Cuánto mide el ángulo central de un <b>${nm}</b>? (En grados.)`,
  rg_ang_s: (n, r) => `La vuelta entera, 360°, se reparte entre ${n} ángulos centrales iguales: 360° : ${n} = <b>${r}°</b>.`,
  rg_per_q: (nm, L) => `¿Cuál es el perímetro de un <b>${nm}</b> de ${L} cm de lado? (En cm.)`,
  rg_per_s: (n, L, P) => `Tiene ${n} lados iguales: no hace falta sumarlos, basta con multiplicar. ${n} × ${L} = <b>${P} cm</b>.`,
  rg_lado_q: (nm, P) => `Un <b>${nm}</b> tiene ${P} cm de perímetro. ¿Cuánto mide cada lado? (En cm.)`,
  rg_lado_s: (n, P, L) => `Sus ${n} lados son iguales: ${P} : ${n} = <b>${L} cm</b>. Compruebo: ${n} × ${L} = ${P} ✔`,
  ej_reg_q: n => `¿Cuántos ejes de simetría tiene un polígono regular de <b>${n} lados</b>?`,
